def _normalizar_nome(nome: str) -> str:
    import unicodedata

    return "".join(
        caractere
        for caractere in unicodedata.normalize("NFKD", nome).casefold()
        if not unicodedata.combining(caractere)
    )


def _obter_estado(
    estado_modelo: type, banco: str, codigo: int, uf: str, nome: str
) -> object:
    estado = estado_modelo.objects.using(banco).filter(uf=uf).first()
    if estado:
        return estado
    estado, criado = estado_modelo.objects.using(banco).get_or_create(
        codigo=codigo,
        defaults={"uf": uf, "nome": nome},
    )
    if not criado and estado.uf != uf:
        message = (
            f"O código de estado {codigo} já está associado à UF {estado.uf}, "
            f"não a {uf}."
        )
        raise RuntimeError(message)
    return estado


def _incluir_municipio(
    municipio_modelo: type,
    estado_modelo: type,
    banco: str,
    codigo: str,
    nome: str,
    uf: str,
    codigo_estado: int,
    nome_estado: str,
) -> object:
    estado = _obter_estado(estado_modelo, banco, codigo_estado, uf, nome_estado)
    municipio, criado = municipio_modelo.objects.using(banco).get_or_create(
        codigo=codigo,
        defaults={"nome": nome, "estado_id": estado.pk},
    )
    if not criado and municipio.estado_id != estado.pk:
        message = f"O código IBGE {codigo} aparece vinculado a mais de uma UF."
        raise RuntimeError(message)
    return municipio


def _vincular_registros(
    modelo: type,
    cidade_modelo: type,
    municipio_modelo: type,
    banco: str,
    por_codigo: dict[str, object],
    por_nome_uf: dict[tuple[str, str], object],
    nome_modelo: str,
) -> None:
    registros_sem_municipio = []
    registros = modelo.objects.using(banco).select_related("cidade__estado")
    for registro in registros:
        cidade = cidade_modelo.objects.using(banco).get(pk=registro.cidade_id)
        codigo = registro.codigo_ibge.strip()
        municipio = por_codigo.get(codigo) if len(codigo) == 7 else None
        if municipio is None:
            estado_cidade = cidade.estado
            chave = (
                estado_cidade.uf.casefold(),
                _normalizar_nome(cidade.cidade),
            )
            municipio = por_nome_uf.get(chave)
        if municipio is None and len(codigo) == 7 and codigo.isdecimal():
            estado_cidade = cidade.estado
            municipio = _incluir_municipio(
                municipio_modelo,
                type(estado_cidade),
                banco,
                codigo,
                cidade.cidade,
                estado_cidade.uf,
                estado_cidade.codigo,
                estado_cidade.nome,
            )
            por_codigo[codigo] = municipio
            por_nome_uf[
                (estado_cidade.uf.casefold(), _normalizar_nome(cidade.cidade))
            ] = municipio
        if municipio is None:
            registros_sem_municipio.append(registro.pk)
            continue
        registro.municipio_id = municipio.pk
        registro.save(using=banco, update_fields=["municipio"])

    if registros_sem_municipio:
        ids = ", ".join(str(pk) for pk in registros_sem_municipio[:20])
        message = (
            f"Não foi possível converter {nome_modelo} (IDs: {ids}) para um "
            "município IBGE. Corrija ou complete os códigos IBGE antes de "
            "aplicar esta migração."
        )
        raise RuntimeError(message)


def migrar_localidades(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    banco = schema_editor.connection.alias
    estado_modelo = apps.get_model("sistema", "Estado")
    municipio_modelo = apps.get_model("sistema", "Municipio")
    cidade_modelo = apps.get_model("sistema", "Cidade")
    codigo_modelo = apps.get_model("sistema", "CodigoIBGE")

    por_codigo = {}
    for codigo, nome, uf, codigo_estado, nome_estado in (
        codigo_modelo.objects.using(banco)
        .order_by("codigo_cidade", "codigo_estado", "empresa")
        .values_list("codigo_cidade", "nome_cidade", "uf", "codigo_estado", "nome_uf")
    ):
        if len(codigo) != 7 or not codigo.isdecimal():
            continue
        por_codigo[codigo] = _incluir_municipio(
            municipio_modelo,
            estado_modelo,
            banco,
            codigo,
            nome,
            uf,
            codigo_estado,
            nome_estado,
        )

    por_nome_uf = {
        (
            municipio.estado.uf.casefold(),
            _normalizar_nome(municipio.nome),
        ): municipio
        for municipio in municipio_modelo.objects.using(banco).select_related("estado")
    }

    for modelo, nome_modelo in (
        (apps.get_model("sistema", "Empresa"), "empresas"),
        (apps.get_model("sistema", "Fazenda"), "fazendas"),
    ):
        _vincular_registros(
            modelo,
            cidade_modelo,
            municipio_modelo,
            banco,
            por_codigo,
            por_nome_uf,
            nome_modelo,
        )


